import{_ as r,C as o,o as s,c as n,j as a,a as t,E as d,ag as l}from"./chunks/framework.DMVuHR7L.js";const y=JSON.parse('{"title":"Dashboard & layout","description":"","frontmatter":{},"headers":[],"relativePath":"features/dashboard.md","filePath":"features/dashboard.md","lastUpdated":1778531678000}'),h={name:"features/dashboard.md"};function g(c,e,p,u,m,b){const i=o("ThemeImage");return s(),n("div",null,[e[0]||(e[0]=a("h1",{id:"dashboard-layout",tabindex:"-1"},[t("Dashboard & layout "),a("a",{class:"header-anchor",href:"#dashboard-layout","aria-label":'Permalink to "Dashboard & layout"'},"​")],-1)),e[1]||(e[1]=a("p",null,[t("The connected app is a "),a("strong",null,"dwindle binary-tree layout"),t(" of widget tiles, the same family of layouts you'd find in tiling window managers like Hyprland. Every tile has the same chrome — a header, an optional toolbar, the widget itself, and a corner grip — and they share every pixel of available space.")],-1)),d(i,{"src-dark":"/img/features/dashboard-multi.png","src-light":"/img/features/dashboard-multi-light.png",alt:"Dashboard layout"}),e[2]||(e[2]=l('<h2 id="adding-and-removing-widgets" tabindex="-1">Adding and removing widgets <a class="header-anchor" href="#adding-and-removing-widgets" aria-label="Permalink to &quot;Adding and removing widgets&quot;">​</a></h2><ul><li><strong>+ Add widget</strong> in the topbar opens the <a href="./settings#palette">palette</a>. Picking a kind splits the focused tile in two, with the new widget occupying half the previous space.</li><li><strong>× Close</strong> in a tile&#39;s header removes it. The surviving sibling expands to fill the freed area.</li><li><strong>Clear layout</strong> empties the dashboard back to its empty CTA. Useful when you want to redraw from scratch.</li></ul><h2 id="rearranging" tabindex="-1">Rearranging <a class="header-anchor" href="#rearranging" aria-label="Permalink to &quot;Rearranging&quot;">​</a></h2><ul><li><strong>Swap by dragging the header.</strong> Grab a tile by its header and drop it on another tile — they swap positions in the tree without resizing.</li><li><strong>Resize the seam.</strong> Hover the seam between two tiles; the cursor turns into a resize handle. Drag to redistribute space between siblings.</li><li><strong>Maximize.</strong> The square icon in a tile&#39;s header pops it to fill the entire dashboard. Click again (now a <em>Restore</em> icon) to drop back.</li><li><strong>Hide the chrome.</strong> The eye icon in the header cycles between <em>show everything</em> → <em>hide the toolbar</em> → <em>hide the toolbar <strong>and</strong> the header</em>. Use it when you want a tile to read like an embedded panel.</li></ul><h2 id="undo-and-redo" tabindex="-1">Undo and redo <a class="header-anchor" href="#undo-and-redo" aria-label="Permalink to &quot;Undo and redo&quot;">​</a></h2><ul><li><strong>⌘Z / Ctrl+Z</strong> undoes the last layout-changing action — adding a tile, removing it, swapping, resizing, maximize, clear-layout. The history buffer lives inside the tile grid; reloading the page persists the current layout but not the undo stack.</li><li><strong>⌘⇧Z / Ctrl+Shift+Z</strong> redoes.</li></ul><p>The shortcut is suppressed when the focus is inside a text field, so the browser&#39;s native undo for typing keeps working.</p><h2 id="persistence" tabindex="-1">Persistence <a class="header-anchor" href="#persistence" aria-label="Permalink to &quot;Persistence&quot;">​</a></h2><p>Layouts and per-widget settings persist in <code>localStorage</code> per device serial:</p><ul><li>The tree itself: <code>weblogcat-dashboard-v2</code>.</li><li>Per-widget state: keyed by <code>weblogcat:&lt;kind&gt;:&lt;serial&gt;:&lt;tileId&gt;</code> so two Logcat tiles on the same device keep independent filter setups across reloads.</li></ul><p>Switching to a different device wakes that device&#39;s saved layout. The demo device has its own separate slot.</p><h2 id="sharing-a-layout-via-url" tabindex="-1">Sharing a layout via URL <a class="header-anchor" href="#sharing-a-layout-via-url" aria-label="Permalink to &quot;Sharing a layout via URL&quot;">​</a></h2><p>The dashboard URL accepts a <code>?d=&lt;encoded&gt;</code> query string that captures the current layout + tile settings. Clicking <strong>Share</strong> in the dashboard copies a link with the current state encoded. Recipients open the link, pair their own device, and land on your exact layout — chip filters and all.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>URL state is <strong>read-forward compatible</strong>: WebLogcat keeps accepting older <code>?d=</code> payload shapes so links you sent last month still resolve. See the note in <a href="./../devs/release-plan">release plan</a> for the long-term contract.</p></div>',14))])}const w=r(h,[["render",g]]);export{y as __pageData,w as default};
